def _is_localhost_address(host: str) -> bool:
    """Check if host is a localhost-like address (127.0.0.1, 169.254.169.254, ::1, or mapped decimal)."""
    # Check for localhost IPs
    if host == '127.0.0.1' or host == '169.254.169.254' or host == '::1':
