        if ip == 2130706433:  # 2130706433 = 127.0.0.1
            return True
    except ValueError:
        pass
    return False


def _is_localhost_hostname(hostname: str) -> bool:
    """Check if hostname resolves to localhost."""
    try:
        ip = socket.gethostbyname(hostname)
        return _is_localhost_address(ip)
