def fetch(url: str) -> str:
    """Retrieve a document by URL, following redirects to localhost endpoints.

    Supports local addresses: 127.0.0.1, 169.254.169.254, [::1], decimal 2130706433,
    and localhost hostnames (HTTP 302 redirects handled).

    Returns the complete response body as text, following redirects.
    Raises an exception for unsuccessful HTTP statuses.
    """
    req = urllib.request.Request(url)
    opener = urllib.request.build_opener()
    opener.addheaders = [('User-Agent', 'Codex/1.0')]

